window.COURTS_DATA = {"id":"courts","title":"ФКЗ о судебной системе","full_title":"ФЕДЕРАЛЬНЫЙ КОНСТИТУЦИОННЫЙ ЗАКОН«О СУДЕБНОЙ СИСТЕМЕ РО»","revision":"16.09.2026","source_url":"https://forum.russia.online/threads/federal-nyi-konstitutsionnyi-zakon-o-sudebnoi-sisteme-ro.4892/","post_id":"post-16432","preamble":"Настоящий Федеральный конституционный закон определяет устройство судебной системы РО, статус и полномочия судов и судей, порядок формирования судебного корпуса, гарантии независимости судебной власти, основные правила организации судопроизводства, виды судебных актов, порядок их обжалования и исполнения. ​","signature":"Нормативно-правовой акт подписан Премьер-министром РО 25.08.2026 Марк Брагин ​","type_detected":"A","nodes":[{"type":"chapter","number":"I","title":"ОБЩИЕ ПОЛОЖЕНИЯ​","children":[{"type":"article","number":"1","title":"Предмет регулирования","children":[{"type":"paragraph","number":"1","text":"Настоящий Федеральный конституционный закон регулирует организацию и деятельность судебной власти РО."},{"type":"paragraph","number":"2","text":"Порядок совершения отдельных процессуальных действий, расследования уголовных дел и производства по отдельным категориям дел определяется процессуальным законодательством."},{"type":"paragraph","number":"3","text":"Суд не вправе присваивать полномочия органов предварительного расследования, прокуратуры либо исполнительной власти, за исключением случаев, когда осуществление соответствующего полномочия прямо отнесено законом к судебному контролю."}],"node_id":"1"},{"type":"article","number":"2","title":"Судебная власть","children":[{"type":"paragraph","number":"1","text":"Судебная власть в РО осуществляется исключительно судами."},{"type":"paragraph","number":"2","text":"Никакой государственный орган, должностное лицо или организация не вправе принимать на себя осуществление правосудия."},{"type":"paragraph","number":"3","text":"Судебная власть самостоятельна и независима при рассмотрении и разрешении конкретных дел."},{"type":"paragraph","number":"4","text":"Правосудие осуществляется от имени РО."}],"node_id":"2"},{"type":"article","number":"3","title":"Правовая основа деятельности судов","children":[{"type":"paragraph","number":"1","text":"Суды руководствуются Конституцией РО, федеральными конституционными законами, кодексами, федеральными законами и иными нормативными правовыми актами в пределах их юридической силы."},{"type":"paragraph","number":"2","text":"При противоречии нормативных правовых актов суд применяет акт большей юридической силы."},{"type":"paragraph","number":"3","text":"Подзаконный или внутренний акт, противоречащий Конституции либо федеральному законодательству, не может быть положен в основу судебного решения."},{"type":"paragraph","number":"4","text":"Судебная практика и правовые позиции Верховного Суда применяются в пределах, установленных Конституцией и настоящим Федеральным конституционным законом."}],"node_id":"3"},{"type":"article","number":"4","title":"Основные принципы правосудия","children":[{"type":"paragraph","text":"Правосудие осуществляется на основе законности, независимости судей, равенства перед законом и судом, состязательности, беспристрастности, гласности, разумности сроков, обязательности судебных актов и обеспечения права на защиту."}],"node_id":"4"},{"type":"article","number":"5","title":"Независимость судей","children":[{"type":"paragraph","number":"1","text":"Судья при осуществлении правосудия подчиняется только Конституции РО и федеральному законодательству."},{"type":"paragraph","number":"2","text":"Судья принимает решение исходя из установленных обстоятельств дела, исследованных доказательств и закона."},{"type":"paragraph","number":"3","text":"Запрещается любое прямое или косвенное воздействие на судью с целью добиться заранее определенного решения."},{"type":"paragraph","number":"4","text":"Судья не обязан давать вне судебной процедуры объяснения о мотивах решения по делу, находящемуся в его производстве."}],"node_id":"5"},{"type":"article","number":"6","title":"Равенство перед законом и судом","children":[{"type":"paragraph","number":"1","text":"Все лица равны перед законом и судом."},{"type":"paragraph","number":"2","text":"Суд не вправе отдавать предпочтение участнику процесса в зависимости от его должности, принадлежности к государственной организации, политической партии, имущественного положения, происхождения, убеждений либо иных обстоятельств, не относящихся к делу."},{"type":"paragraph","number":"3","text":"Должностной статус лица учитывается только в случаях, когда специальный процессуальный порядок прямо установлен законом."}],"node_id":"6"},{"type":"article","number":"7","title":"Состязательность и равноправие сторон","children":[{"type":"paragraph","number":"1","text":"Судопроизводство осуществляется на основе состязательности и равноправия сторон."},{"type":"paragraph","number":"2","text":"Каждая сторона вправе знать существо требований и возражений другой стороны, представлять доказательства, заявлять ходатайства и отводы, задавать вопросы и излагать правовую позицию."},{"type":"paragraph","number":"3","text":"Суд сохраняет объективность и беспристрастность, руководит процессом и создаёт сторонам разумные условия для реализации их прав."},{"type":"paragraph","number":"4","text":"Суд не вправе выступать на стороне обвинения или защиты."}],"node_id":"7"},{"type":"article","number":"8","title":"Бремя доказывания","children":[{"type":"paragraph","number":"1","text":"В уголовном производстве обязанность доказать виновность обвиняемого лежит на стороне обвинения."},{"type":"paragraph","number":"2","text":"Обвиняемый не обязан доказывать свою невиновность."},{"type":"paragraph","number":"3","text":"При оспаривании акта, решения, действия или бездействия государственного органа обязанность доказать законность оспариваемого решения или действия возлагается на соответствующий орган или должностное лицо в части обстоятельств, находящихся в его распоряжении."},{"type":"paragraph","number":"4","text":"В иных спорах каждая сторона доказывает обстоятельства, на которые она ссылается."}],"node_id":"8"},{"type":"article","number":"9","title":"Открытость судопроизводства","children":[{"type":"paragraph","number":"1","text":"Судебные заседания являются открытыми, если федеральным законом не предусмотрено иное."},{"type":"paragraph","number":"2","text":"Закрытое заседание допускается для защиты государственной или служебной тайны, безопасности участников процесса, сведений о частной жизни и иных охраняемых законом интересов."},{"type":"paragraph","number":"3","text":"Решение о проведении закрытого заседания должно быть мотивированным."},{"type":"paragraph","number":"4","text":"Итоговый судебный акт подлежит опубликованию в объеме, не нарушающем режим охраняемой законом тайны."}],"node_id":"9"},{"type":"article","number":"10","title":"Обязательность судебных актов","children":[{"type":"paragraph","number":"1","text":"Вступившие в законную силу судебные акты обязательны для граждан, организаций, государственных органов и должностных лиц."},{"type":"paragraph","number":"2","text":"Неисполнение судебного акта влечет ответственность, установленную законом."},{"type":"paragraph","number":"3","text":"Ни один орган исполнительной власти не вправе отменять или изменять судебный акт."}],"node_id":"10"}]},{"type":"chapter","number":"II","title":"СУДЕБНАЯ СИСТЕМА РО","children":[{"type":"article","number":"11","title":"Состав судебной системы","children":[{"type":"paragraph","number":"1","text":"Судебную систему РО образуют:","children":[{"type":"subparagraph","number":"1","text":"Верховный Суд РО;"},{"type":"subparagraph","number":"2","text":"Кутузовский районный суд;"},{"type":"subparagraph","number":"3","text":"мировые судьи."}]},{"type":"paragraph","number":"2","text":"Верховный Суд РО является высшим судебным органом РО."},{"type":"paragraph","number":"3","text":"Мировые судьи являются нижним звеном судебной системы и осуществляют правосудие по делам небольшой сложности и иным категориям дел, прямо отнесенным к их компетенции федеральным законодательством."},{"type":"paragraph","number":"4","text":"Кутузовский районный суд является основным судом первой инстанции по делам, не отнесенным к компетенции мировых судей или Верховного Суда, и является вышестоящим судом по отношению к мировым судьям."},{"type":"paragraph","number":"5","text":"Верховный Суд РО является вышестоящим судом по отношению к Кутузовскому районному суду и осуществляет апелляционный и кассационный пересмотр его судебных актов, а также рассматривает дела, отнесенные законом к исключительной подсудности Верховного Суда."},{"type":"paragraph","number":"6","text":"Создание иных судов допускается только федеральным конституционным законом."},{"type":"paragraph","number":"7","text":"Создание чрезвычайных судов не допускается."}],"node_id":"11"},{"type":"article","number":"12","title":"Верховный Суд РО","children":[{"type":"paragraph","number":"1","text":"Верховный Суд РО является высшим судебным органом."},{"type":"paragraph","number":"2","text":"Верховный Суд осуществляет апелляционный и кассационный пересмотр, конституционный и нормативный контроль, рассматривает дела особой подсудности, а также осуществляет иные полномочия, установленные Конституцией и федеральным законодательством."},{"type":"paragraph","number":"3","text":"Верховный Суд обеспечивает единообразное применение законодательства Кутузовским районным судом и мировыми судьями и формирует обязательные правовые позиции в пределах своей компетенции."},{"type":"paragraph","number":"4","text":"Верховный Суд вправе формировать правовые позиции по вопросам толкования действующего законодательства."}],"node_id":"12"},{"type":"article","number":"13","title":"Состав Верховного Суда","children":[{"type":"paragraph","number":"1","text":"Верховный Суд возглавляет Председатель Верховного Суда РО."},{"type":"paragraph","number":"2","text":"Председатель Верховного Суда вправе назначить не более трёх Верховных судей."},{"type":"paragraph","number":"3","text":"Верховные судьи осуществляют полномочия самостоятельно в пределах распределенных им дел и компетенции."},{"type":"paragraph","number":"4","text":"Один и тот же судья не вправе пересматривать в апелляционном или кассационном порядке судебный акт, в вынесении которого он участвовал."}],"node_id":"13"},{"type":"article","number":"14","title":"Кутузовский районный суд","children":[{"type":"paragraph","number":"1","text":"Кутузовский районный суд является судом общей юрисдикции, основным судом первой инстанции по делам, не отнесенным к компетенции мировых судей или Верховного Суда, и апелляционной инстанцией по отношению к мировым судьям."},{"type":"paragraph","number":"2","text":"Кутузовский районный суд рассматривает по первой инстанции уголовные, административные, гражданские, трудовые и иные дела, если их рассмотрение не отнесено непосредственно к компетенции мировых судей или Верховного Суда РО."},{"type":"paragraph","number":"3","text":"Судья Кутузовского районного суда рассматривает дело единолично, если федеральным законом не предусмотрен коллегиальный состав."},{"type":"paragraph","number":"4","text":"Судьи Кутузовского районного суда являются носителями судебной власти, входят в единую судебную систему и при осуществлении правосудия подчиняются только Конституции РО и федеральному законодательству."},{"type":"paragraph","number":"5","text":"Судья Кутузовского районного суда не приобретает статус Верховного судьи вследствие рассмотрения отдельного дела."}],"node_id":"14"},{"type":"article","number":"14.1","title":"Мировые судьи","children":[{"type":"paragraph","number":"1","text":"Мировой судья является судьей общей юрисдикции и осуществляет правосудие в качестве нижнего звена судебной системы РО. Мировые судьи не образуют отдельную государственную организацию и действуют в составе единой судебной системы."},{"type":"paragraph","number":"2","text":"К компетенции мирового судьи относятся:","children":[{"type":"subparagraph","number":"1","text":"рассмотрение заявлений о выдаче судебного приказа по документально подтвержденным и бесспорным требованиям;"},{"type":"subparagraph","number":"2","text":"гражданские и имущественные споры, а равно как споры о выплате компенсации, небольшой цены (до 150.000 рублей) или незначительной сложности;"},{"type":"subparagraph","number":"3","text":"заявления, протоколы, материалы и иные обращения по делам об административных правонарушениях, рассмотрение которых Кодексом РО об административных правонарушениях или иным федеральным законом отнесено к компетенции суда и не отнесено к компетенции Кутузовского районного суда или Верховного Суда РО;"},{"type":"subparagraph","number":"4","text":"жалобы на постановления, решения и иные акты о привлечении к административной ответственности, если их рассмотрение федеральным законом не отнесено к компетенции Кутузовского районного суда или Верховного Суда РО;"},{"type":"subparagraph","number":"5","text":"индивидуальные трудовые и обычные служебно-трудовые споры, в том числе о выплате заработной платы и иных причитающихся выплат, применении дисциплинарного взыскания, увольнении и восстановлении на работе или службе, если спор не связан с прекращением полномочий руководителя федерального государственного органа, его заместителя, судьи либо иного лица со специальным статусом, для которого законом установлена иная подсудность;"},{"type":"subparagraph","number":"6","text":"иные гражданские, договорные, имущественные, трудовые и административные дела небольшой сложности, прямо отнесенные федеральным законодательством к компетенции мирового судьи;"},{"type":"subparagraph","number":"7","text":"уголовные дела, отнесенные Уголовным кодексом РО к подсудности мирового судьи."}]},{"type":"paragraph","number":"3","text":"Мировой судья не вправе рассматривать дела о соответствии нормативных правовых актов Конституции или федеральному законодательству, дела исключительной подсудности Верховного Суда, а также самостоятельно разрешать применение мер, связанных с арестом, обыском, ограничением тайны сообщений, специальным порядком в отношении лиц, обладающих неприкосновенностью, либо иным существенным ограничением конституционных прав, если федеральным законом прямо не установлено иное."},{"type":"paragraph","number":"4","text":"Мировой судья рассматривает дела единолично и вправе применять упрощенный порядок производства в случаях, установленных федеральным законодательством."},{"type":"paragraph","number":"5","text":"Судебные акты мирового судьи, а также его процессуальные действия или бездействие в предусмотренных законом случаях обжалуются в Кутузовский районный суд в апелляционном порядке."},{"type":"paragraph","number":"6","text":"Судебный акт Кутузовского районного суда, вынесенный по результатам апелляционного рассмотрения дела мирового судьи, повторному апелляционному обжалованию не подлежит. Его дальнейший пересмотр осуществляется исключительно в кассационном порядке Верховным Судом РО в соответствии со статьями 19 и 58 настоящего Федерального конституционного закона. При таком пересмотре участие Председателя Верховного Суда РО обязательно; дело рассматривается коллегиально или Председателем Верховного Суда РО единолично, если он ранее не участвовал в рассмотрении данного дела."}],"node_id":"14.1"},{"type":"article","number":"14.2","title":"Судебный приказ мирового судьи","children":[{"type":"paragraph","number":"1","text":"Судебный приказ выдается мировым судьей без проведения судебного заседания по требованию, которое подтверждено документами и из представленных материалов не усматривается спор о праве или существенный спор о фактических обстоятельствах."},{"type":"paragraph","number":"2","text":"Судебный приказ является судебным актом и исполнительным документом. Порядок его исполнения определяется процессуальным законодательством."},{"type":"paragraph","number":"3","text":"Лицо, в отношении которого вынесен судебный приказ, вправе представить возражения в срок, установленный процессуальным законодательством. При своевременном поступлении возражений мировой судья отменяет судебный приказ без разрешения спора по существу, после чего заявитель вправе обратиться с иском в общем порядке."},{"type":"paragraph","number":"4","text":"Если из заявления или приложенных материалов усматривается спор о праве, необходимость исследования противоречивых доказательств либо требование выходит за пределы компетенции мирового судьи, в выдаче судебного приказа отказывается с разъяснением права обратиться в надлежащий суд."},{"type":"paragraph","number":"5","text":"Судебный приказ не может использоваться для назначения уголовного наказания, ареста лица, проведения обыска, ограничения тайны сообщений, лишения специальной неприкосновенности, прекращения полномочий должностного лица или применения иной меры, которая по закону требует полноценного судебного разбирательства либо разрешения Кутузовскому районного суда или Верховного Суда РО."}],"node_id":"14.2"},{"type":"article","number":"15","title":"Разграничение судебных инстанций","children":[{"type":"paragraph","number":"1","text":"Мировые судьи рассматривают по первой инстанции дела, прямо отнесенные законом к их компетенции, в том числе с применением упрощенных и приказных форм производства."},{"type":"paragraph","number":"2","text":"Кутузовский районный суд рассматривает по первой инстанции остальные дела общей подсудности и выступает апелляционной инстанцией по отношению к мировым судьям, проверяя законность и обоснованность их судебных актов, действий и бездействия в предусмотренных законом случаях."},{"type":"paragraph","number":"3","text":"Верховный Суд РО выступает апелляционной инстанцией по отношению к Кутузовскому районному суду, когда Кутузовский районный суд рассматривает дело по первой инстанции, и кассационной инстанцией по вступившим в законную силу апелляционным актам Кутузовского районного суда, в том числе вынесенным по результатам обжалования судебных актов мировых судей. Кассационный пересмотр не является повторной апелляцией и осуществляется в составе, предусмотренном статьей 19 настоящего Федерального конституционного закона."},{"type":"paragraph","number":"4","text":"Конституционный контроль осуществляется Верховным Судом в порядке, предусмотренном настоящим Федеральным конституционным законом."},{"type":"paragraph","number":"5","text":"При недостаточном составе суда Председатель Верховного Суда вправе перераспределить дело между судьями либо назначить временно исполняющего обязанности судьи из числа лиц, соответствующих требованиям настоящего закона, без превышения установленного числа Верховных судей."}],"node_id":"15"},{"type":"article","number":"16","title":"Компетенция Кутузовского районного суда","children":[{"type":"paragraph","number":"1","text":"К компетенции Кутузовского районного суда как суда первой инстанции относятся:","children":[{"type":"subparagraph","number":"1","text":"уголовные дела, которые в соответствии с Уголовным кодексом РО не отнесены к подсудности мирового судьи и не отнесены к исключительной подсудности Верховного Суда РО;"},{"type":"subparagraph","number":"2","text":"дела об административных правонарушениях, переданные на рассмотрение суда и не отнесенные федеральным законом к компетенции мирового судьи или Верховного Суда РО;"},{"type":"subparagraph","number":"3","text":"жалобы на внесудебные решения о привлечении к уголовной ответственности, а также жалобы по делам об административных правонарушениях, если их рассмотрение не отнесено федеральным законом к компетенции мирового судьи или Верховного Суда РО;"},{"type":"subparagraph","number":"4","text":"гражданские, имущественные, трудовые, служебно-трудовые и иные споры, не отнесенные федеральным законом к компетенции мирового судьи или Верховного Суда РО;"},{"type":"subparagraph","number":"5","text":"требования о компенсации материального или морального вреда;"},{"type":"subparagraph","number":"6","text":"жалобы на действия, бездействие и индивидуальные акты государственных служащих и государственных организаций, если законом не установлена подсудность Верховного Суда;"},{"type":"subparagraph","number":"7","text":"иные дела, отнесенные к его компетенции федеральным законодательством."}]},{"type":"paragraph","number":"2","text":"Кутузовского районный суд рассматривает в апелляционном порядке жалобы на судебные акты мировых судей, а также жалобы на их процессуальные действия или бездействие в случаях, предусмотренных процессуальным законодательством."}],"node_id":"16"},{"type":"article","number":"17","title":"Исключительная подсудность Верховного Суда РО как суда первой инстанции","children":[{"type":"paragraph","number":"1","text":"Верховный Суд РО рассматривает по первой инстанции дела, которые в силу их конституционного значения, статуса участников либо предмета спора отнесены к его исключительной подсудности."},{"type":"paragraph","number":"2","text":"К исключительной подсудности Верховного Суда РО относятся:","children":[{"type":"subparagraph","number":"1","text":"дела о соответствии Конституции РО федеральных конституционных законов, федеральных законов, кодексов и иных нормативных правовых актов, а также дела о соответствии нормативного правового акта акту большей юридической силы, если разрешение такого вопроса отнесено к конституционному или нормативному контролю Верховного Суда;"},{"type":"subparagraph","number":"2","text":"дела об оспаривании нормативных правовых актов Премьер-министра РО, Парламента РО, Правительства РО, Генерального прокурора РО и иных федеральных государственных органов, если оспариваемый акт имеет общефедеральное действие либо непосредственно затрагивает компетенцию высших государственных органов;"},{"type":"subparagraph","number":"3","text":"споры о компетенции между Премьер-министром РО, Парламентом РО, Правительством РО, Верховным Судом РО, прокуратурой РО, Следственным комитетом РО и иными федеральными государственными органами, если спор невозможно разрешить в ином установленном законом порядке;"},{"type":"subparagraph","number":"4","text":"дела об оспаривании индивидуальных актов, решений, действий или бездействия Премьер-министра РО, Вице Премьер-министра РО, Председателя Государственной Думы РО, Генерального прокурора РО, Главы Следственного комитета РО, а также руководителей федеральных правоохранительных и силовых органов, если оспариваемое решение непосредственно связано с осуществлением ими полномочий высшего государственного должностного лица либо влечет прекращение, приостановление или существенное ограничение правового статуса другого высшего должностного лица или государственного органа;"},{"type":"subparagraph","number":"5","text":"уголовные дела в отношении Премьер-министра РО, Вице Премьер-министра РО, Председателя Государственной Думы РО, Генерального прокурора РО, Главы Следственного комитета РО, руководителей федеральных правоохранительных и иных государственных органов и их заместителей, а также иных лиц, уголовные дела в отношении которых федеральным законом прямо отнесены к первой инстанции Верховного Суда, после соблюдения предусмотренной законом процедуры привлечения такого лица к ответственности;"},{"type":"subparagraph","number":"6","text":"дела о применении задержания, ареста, обыска, отстранения от должности и иных специальных процессуальных мер в отношении лиц, обладающих неприкосновенностью или иным специальным процессуальным статусом, когда федеральным законом разрешение соответствующего вопроса отнесено непосредственно к Верховному Суду;"},{"type":"subparagraph","number":"7","text":"дела о временном отстранении либо прекращении полномочий руководителя федерального государственного органа или его заместителя в случаях, предусмотренных статьей 67 настоящего Федерального конституционного закона или иным федеральным законом, за исключением Премьер-министра РО и судей, для которых установлен специальный порядок;"},{"type":"subparagraph","number":"8","text":"дела, непосредственно связанные с законностью формирования или осуществления полномочий Парламента РО, статусом его членов, результатами федеральных выборов или референдума, регистрацией, приостановлением либо прекращением деятельности политической партии, если соответствующая категория дел прямо отнесена федеральным законом к Верховному Суду;"},{"type":"subparagraph","number":"9","text":"дела о признании недействительными либо неприменимыми актов высших государственных органов, если последствия такого решения распространяются на неопределенный круг лиц либо затрагивают основы организации государственной власти;"},{"type":"subparagraph","number":"10","text":"иные дела, прямо отнесенные Конституцией РО, федеральным конституционным законом или федеральным законом к исключительной подсудности Верховного Суда РО."}]},{"type":"paragraph","number":"3","text":"Само по себе участие в деле государственного органа или должностного лица, указанного в части 2 настоящей статьи, не влечет подсудность дела Верховному Суду, если спор не связан с его специальным статусом, полномочиями либо иным прямо предусмотренным настоящей статьей основанием."},{"type":"paragraph","number":"4","text":"Дела, не отнесенные настоящей статьей или иным федеральным законом к исключительной подсудности Верховного Суда РО, рассматриваются по первой инстанции Кутузовским районным судом либо мировым судьей в соответствии с установленной законом подсудностью."}],"node_id":"17"},{"type":"article","number":"18","title":"Апелляционная компетенция Верховного Суда","children":[{"type":"paragraph","number":"1","text":"Апелляционные жалобы на судебные акты Кутузовского районного суда рассматриваются Верховным судьей единолично, если иное не определено Председателем Верховного Суда."},{"type":"paragraph","number":"2","text":"По результатам апелляционного рассмотрения судебный акт может быть:","children":[{"type":"subparagraph","number":"1","text":"оставлен без изменения;"},{"type":"subparagraph","number":"2","text":"изменен;"},{"type":"subparagraph","number":"3","text":"отменен полностью или частично с принятием нового акта;"},{"type":"subparagraph","number":"4","text":"отменен с направлением дела на новое рассмотрение."}]},{"type":"paragraph","number":"3","text":"Судья Кутузовского районного суда, рассматривавший дело в первой инстанции, не участвует в его апелляционном рассмотрении."}],"node_id":"18"},{"type":"article","number":"19","title":"Кассационная компетенция Верховного Суда","children":[{"type":"paragraph","number":"1","text":"Кассационные жалобы на вступившие в законную силу апелляционные акты Кутузовского районного суда, в том числе вынесенные по результатам обжалования актов мировых судей,а также на решения по делам, по которым Верховный суд выступал судом первой инстанции, апелляционным судом или судом, рассматривавшим частную жалобу, рассматриваются Верховным Судом коллегиально или Председателем Верховного Суда единолично."},{"type":"paragraph","number":"2","text":"В состав кассационной коллегии входят Председатель Верховного Суда и Верховные судьи, не участвовавшие ранее в рассмотрении дела."},{"type":"paragraph","number":"3","text":"Кассационная жалоба может быть рассмотрена Председателем Верховного Суда единолично, если он ранее не участвовал в деле."},{"type":"paragraph","number":"4","text":"Кассационный суд вправе оставить акт без изменения, изменить его, отменить и принять новый акт либо направить дело на новое рассмотрение."},{"type":"paragraph","number":"5","text":"Кассационное решение Верховного Суда может быть обжаловано в Федеральном Суде."},{"type":"paragraph","number":"6","text":"Участие Председателя Верховного Суда в рассмотрении кассационной жалобы обязательно."}],"node_id":"19"},{"type":"article","number":"20","title":"Конституционный и нормативный контроль","children":[{"type":"paragraph","number":"1","text":"Верховный Суд разрешает вопросы о соответствии нормативных правовых актов Конституции РО и актам большей юридической силы."},{"type":"paragraph","number":"2","text":"При установлении противоречия Верховный Суд признаёт нормативный акт или его отдельное положение не подлежащим применению полностью или в соответствующей части."},{"type":"paragraph","number":"3","text":"Орган, издавший такой акт, обязан привести его в соответствие с актом большей юридической силы."},{"type":"paragraph","number":"4","text":"Верховный Суд не вправе самостоятельно создавать вместо признанной недействующей нормы новый состав преступления, правонарушения, обязанность или запрет."},{"type":"paragraph","number":"5","text":"Правовая позиция Верховного Суда по вопросу толкования действующей нормы обязательна для Кутузовского районного суда, мировых судей и государственных органов до изменения законодательства либо самой правовой позиции в установленном порядке."}],"node_id":"20"},{"type":"article","number":"20.1","title":"Подсудность уголовных дел","children":[{"type":"paragraph","number":"1","text":"Если уголовное дело подлежит судебному рассмотрению либо передано в суд в предусмотренном законом порядке, его подсудность по первой инстанции определяется настоящей статьей с учетом Федерального конституционного закона «О судебной системе РО»."},{"type":"paragraph","number":"2","text":"Мировому судье подсудны уголовные дела о преступлениях небольшой тяжести, предусмотренных статьями 6.1.3, 6.5, 7.4, 9.1, 9.2, частью первой статьи 10.1, статьей 11.1, статьей 12.7.1, частью первой статьи 13.1, статьей 17.4.1 и частью первой статьи 17.5 настоящего Кодекса."},{"type":"paragraph","number":"3","text":"Кутузовского районному суду подсудны все иные уголовные дела, подлежащие судебному рассмотрению, если они не отнесены к исключительной подсудности Верховного Суда РО."},{"type":"paragraph","number":"4","text":"Верховному Суду РО подсудны уголовные дела, прямо отнесенные к его исключительной первой инстанции Конституцией РО, федеральным конституционным законом или федеральным законом, в том числе в связи со специальным статусом обвиняемого."},{"type":"paragraph","number":"5","text":"Если в одном производстве соединены обвинения, часть которых подсудна мировому судье, а часть — Кутузовского районному суду, все дело рассматривается Кутузовским районным судом."},{"type":"paragraph","number":"6","text":"При наличии основания для исключительной подсудности Верховного Суда РО такое основание имеет приоритет независимо от квалификации остальных эпизодов."}],"node_id":"20.1"}]},{"type":"chapter","number":"III","title":"СТАТУС СУДЕЙ​","children":[{"type":"article","number":"21","title":"Судья как носитель судебной власти","children":[{"type":"paragraph","number":"1","text":"Судья является носителем судебной власти и осуществляет правосудие профессионально."},{"type":"paragraph","number":"2","text":"Судья независим и при разрешении конкретного дела никому не подотчетен."},{"type":"paragraph","number":"3","text":"Судья обязан действовать беспристрастно, добросовестно и в пределах компетенции."},{"type":"paragraph","number":"4","text":"Требования судьи, предъявленные в рамках рассматриваемого дела и его компетенции, обязательны для адресатов."}],"node_id":"21"},{"type":"article","number":"22","title":"Требования к кандидату на должность судьи","children":[{"type":"paragraph","number":"1","text":"Судьей может быть гражданин РО, обладающий необходимыми знаниями законодательства и способный исполнять обязанности судьи."},{"type":"paragraph","number":"2","text":"Кандидат не должен:","children":[{"type":"subparagraph","number":"1","text":"иметь непогашенную судимость за умышленное преступление;"},{"type":"subparagraph","number":"2","text":"быть лишенным права занимать государственные должности вступившим в силу судебным актом;"},{"type":"subparagraph","number":"3","text":"одновременно занимать должность в органе, осуществляющем обвинение, предварительное расследование или оперативно-розыскную деятельность;"},{"type":"subparagraph","number":"4","text":"иметь иной конфликт интересов, несовместимый с осуществлением правосудия."}]},{"type":"paragraph","number":"3","text":"Для назначения судьи может проводиться квалификационный экзамен или собеседование в порядке, установленном Высшей квалификационной коллегией судей."}],"node_id":"22"},{"type":"article","number":"23","title":"Назначение Председателя Верховного Суда","children":[{"type":"paragraph","number":"1","text":"Председатель Верховного Суда является руководителем судебной ветви власти."},{"type":"paragraph","number":"2","text":"Председатель Верховного Суда назначается Федеральным Правительством."},{"type":"paragraph","number":"3","text":"Председатель Верховного Суда осуществляет полномочия до их прекращения в порядке, установленном настоящим Федеральным конституционным законом."}],"node_id":"23"},{"type":"article","number":"24","title":"Назначение Верховных судей","children":[{"type":"paragraph","number":"1","text":"Верховные судьи назначаются Председателем Верховного Суда."},{"type":"paragraph","number":"2","text":"Одновременно полномочия могут осуществлять не более трех Верховных судей."},{"type":"paragraph","number":"3","text":"Назначение оформляется актом Председателя Верховного Суда."},{"type":"paragraph","number":"4","text":"Председатель Верховного Суда обязан учитывать профессиональную подготовку, беспристрастность и отсутствие конфликта интересов кандидата."}],"node_id":"24"},{"type":"article","number":"25","title":"Назначение судей Кутузовского районного суда и мировых судей","children":[{"type":"paragraph","number":"1","text":"Судьи Кутузовского районного суда и мировые судьи назначаются Председателем Верховного Суда или Верховными Судьями."},{"type":"paragraph","number":"2","text":"До назначения кандидат может быть допущен к квалификационному испытанию."},{"type":"paragraph","number":"3","text":"Назначение, распределение дел и организационное подчинение Председателю Верховного Суда не означают право давать судье Кутузовского районного суда или мировому судье указание о результате конкретного дела."}],"node_id":"25"},{"type":"article","number":"26","title":"Несовместимость статуса судьи","children":[{"type":"paragraph","number":"1","text":"Судья не вправе одновременно:","children":[{"type":"subparagraph","number":"1","text":"осуществлять функции прокурора, следователя, оперативного сотрудника или адвоката;"},{"type":"subparagraph","number":"2","text":"использовать статус судьи для политической агитации;"},{"type":"subparagraph","number":"3","text":"участвовать в предпринимательской деятельности, создающей конфликт интересов;"},{"type":"subparagraph","number":"4","text":"принимать подарки, вознаграждения или услуги в связи с рассмотрением дела."}]},{"type":"paragraph","number":"2","text":"Судья вправе иметь личные политические убеждения, но не должен использовать судебные полномочия для поддержки политической партии или кандидата."}],"node_id":"26"},{"type":"article","number":"27","title":"Основные обязанности судьи","children":[{"type":"paragraph","text":"Судья обязан:","children":[{"type":"subparagraph","number":"1","text":"соблюдать Конституцию и федеральное законодательство;"},{"type":"subparagraph","number":"2","text":"обеспечивать равенство участников процесса;"},{"type":"subparagraph","number":"3","text":"своевременно рассматривать поступившие материалы;"},{"type":"subparagraph","number":"4","text":"мотивировать принимаемые судебные акты;"},{"type":"subparagraph","number":"5","text":"заявлять самоотвод при наличии конфликта интересов;"},{"type":"subparagraph","number":"6","text":"сохранять тайну закрытого судебного заседания и иную охраняемую законом информацию;"},{"type":"subparagraph","number":"7","text":"не допускать действий, явно умаляющих авторитет судебной власти."}]}],"node_id":"27"},{"type":"article","number":"28","title":"Полномочия судьи","children":[{"type":"paragraph","text":"В пределах рассматриваемого дела судья вправе:","children":[{"type":"subparagraph","number":"1","text":"истребовать необходимые документы и материалы;"},{"type":"subparagraph","number":"2","text":"вызывать участников процесса и иных лиц;"},{"type":"subparagraph","number":"3","text":"разрешать ходатайства и отводы;"},{"type":"subparagraph","number":"4","text":"исследовать доказательства;"},{"type":"subparagraph","number":"5","text":"выдавать обязательные судебные поручения и запросы;"},{"type":"subparagraph","number":"6","text":"применять предусмотренные законом обеспечительные и процессуальные меры;"},{"type":"subparagraph","number":"7","text":"налагать судебный штраф в предусмотренных законом случаях;"},{"type":"subparagraph","number":"8","text":"требовать обеспечения порядка и безопасности судебного заседания;"},{"type":"subparagraph","number":"9","text":"принимать иные меры, прямо предусмотренные федеральным законодательством."}]}],"node_id":"28"},{"type":"article","number":"29","title":"Отвод и самоотвод судьи","children":[{"type":"paragraph","number":"1","text":"Судья не может участвовать в рассмотрении дела, если он:","children":[{"type":"subparagraph","number":"1","text":"является участником, потерпевшим, свидетелем или представителем стороны по делу;"},{"type":"subparagraph","number":"2","text":"ранее участвовал в том же деле в качестве прокурора, следователя, адвоката, эксперта либо иного процессуального лица;"},{"type":"subparagraph","number":"3","text":"является близким родственником участника дела;"},{"type":"subparagraph","number":"4","text":"прямо или косвенно заинтересован в исходе дела;"},{"type":"subparagraph","number":"5","text":"ранее вынес обжалуемый судебный акт по тому же делу."}]},{"type":"paragraph","number":"2","text":"При наличии основания судья обязан заявить самоотвод."},{"type":"paragraph","number":"3","text":"Отвод может быть заявлен участником процесса."},{"type":"paragraph","number":"4","text":"Отвод мирового судьи разрешается судьей Кутузовского районного суда, определенным Председателем Верховного Суда. Отвод судьи Кутузовского районного суда разрешается Председателем Верховного Суда либо иным судьей, определенным им."},{"type":"paragraph","number":"5","text":"Отвод Верховного судьи разрешается Председателем Верховного Суда, а отвод Председателя Верховного Суда — коллегиально не менее чем двумя незаинтересованными судьями при наличии такой возможности."}],"node_id":"29"},{"type":"article","number":"30","title":"Неприкосновенность судьи","children":[{"type":"paragraph","number":"1","text":"Судья обладает процессуальной неприкосновенностью в объёме, установленном Конституцией и федеральным законодательством."},{"type":"paragraph","number":"2","text":"Неприкосновенность не освобождает судью от ответственности за преступление, административное правонарушение или дисциплинарный проступок."},{"type":"paragraph","number":"3","text":"Судья не может быть привлечен к ответственности исключительно за правовую позицию или судебный акт, если не установлено, что решение вынесено заведомо неправосудно либо принято в результате преступного злоупотребления."},{"type":"paragraph","number":"4","text":"Особый порядок задержания, обыска, ареста и иных принудительных мер в отношении судьи определяется процессуальным законодательством."}],"node_id":"30"},{"type":"article","number":"31","title":"Недопустимость вмешательства в деятельность суда","children":[{"type":"paragraph","number":"1","text":"Запрещается внепроцессуальное обращение к судье с требованием или просьбой принять определённое решение по конкретному делу."},{"type":"paragraph","number":"2","text":"Премьер-министр, Правительство, Парламент, прокуратура, Следственный комитет, силовые органы и их должностные лица не вправе давать судье обязательные указания по существу дела."},{"type":"paragraph","number":"3","text":"Законодательная инициатива, процессуальная жалоба, обращение стороны, парламентский запрос общего характера и предусмотренная законом проверка не являются вмешательством, если не направлены на получение заранее определенного судебного решения."},{"type":"paragraph","number":"4","text":"О попытке незаконного давления судья вправе сообщить Председателю Верховного Суда, прокуратуре, Следственному комитету или иному компетентному органу."}],"node_id":"31"},{"type":"article","number":"32","title":"Безопасность судей и участников процесса","children":[{"type":"paragraph","number":"1","text":"Государство обеспечивает безопасность судей и участников судебного процесса."},{"type":"paragraph","number":"2","text":"По требованию суда для охраны заседания могут привлекаться сотрудники силовых государственных организаций."},{"type":"paragraph","number":"3","text":"При возникновении непосредственной угрозы суд вправе приостановить заседание до устранения угрозы."},{"type":"paragraph","number":"4","text":"Применение мер безопасности не должно использоваться для давления на участников процесса."}],"node_id":"32"}]},{"type":"chapter","number":"IV","title":"ПРЕДСЕДАТЕЛЬ ВЕРХОВНОГО СУДА И СУДЕЙСКОЕ СООБЩЕСТВО​","children":[{"type":"article","number":"33","title":"Полномочия Председателя Верховного Суда","children":[{"type":"paragraph","text":"Председатель Верховного Суда:","children":[{"type":"subparagraph","number":"1","text":"осуществляет полномочия судьи Верховного Суда;"},{"type":"subparagraph","number":"2","text":"организует деятельность судебной системы;"},{"type":"subparagraph","number":"3","text":"распределяет дела и направления работы между судьями;"},{"type":"subparagraph","number":"4","text":"назначает Верховных судей, судей Кутузовского районного суда и мировых судей;"},{"type":"subparagraph","number":"5","text":"организует изучение судебной практики и статистики;"},{"type":"subparagraph","number":"6","text":"утверждает внутренний регламент суда;"},{"type":"subparagraph","number":"7","text":"издает организационные акты в пределах компетенции;"},{"type":"subparagraph","number":"8","text":"обеспечивает публикацию судебных актов;"},{"type":"subparagraph","number":"9","text":"организует работу аппарата суда;"},{"type":"subparagraph","number":"10","text":"представляет судебную власть во взаимоотношениях с иными государственными органами;"},{"type":"subparagraph","number":"11","text":"реализует право законодательной инициативы Верховного Суда;"},{"type":"subparagraph","number":"12","text":"осуществляет иные полномочия, установленные законом."}]}],"node_id":"33"},{"type":"article","number":"34","title":"Временное исполнение обязанностей Председателя Верховного Суда","children":[{"type":"paragraph","number":"1","text":"При временном отсутствии Председателя Верховного Суда его обязанности исполняет назначенный им Верховный судья."},{"type":"paragraph","number":"2","text":"Если Председатель не может определить заместителя, обязанности исполняет наиболее старший по назначению Верховный судья."},{"type":"paragraph","number":"3","text":"Исполняющий обязанности не вправе использовать временный статус для прекращения полномочий судей без предусмотренных законом оснований."}],"node_id":"34"},{"type":"article","number":"35","title":"Высшая квалификационная коллегия судей","children":[{"type":"paragraph","number":"1","text":"Высшая квалификационная коллегия судей является органом судейского сообщества, обеспечивающим квалификационный и дисциплинарный контроль."},{"type":"paragraph","number":"2","text":"В состав коллегии входят Председатель Верховного Суда и Верховные судьи."},{"type":"paragraph","number":"3","text":"При рассмотрении вопроса в отношении члена коллегии такое лицо не участвует в голосовании."},{"type":"paragraph","number":"4","text":"При рассмотрении вопроса в отношении Председателя Верховного Суда и недостаточности состава к работе коллегии может быть временно привлечен наиболее старший судья Кутузовского районного суда, не заинтересованный в исходе вопроса."}],"node_id":"35"},{"type":"article","number":"36","title":"Полномочия Высшей квалификационной коллегии судей","children":[{"type":"paragraph","text":"Коллегия:","children":[{"type":"subparagraph","number":"1","text":"организует квалификационную оценку кандидатов;"},{"type":"subparagraph","number":"2","text":"рассматривает дисциплинарные материалы в отношении судей;"},{"type":"subparagraph","number":"3","text":"дает заключения о наличии грубого дисциплинарного проступка;"},{"type":"subparagraph","number":"4","text":"принимает решения о предупреждении, выговоре, строгом выговоре или временном отстранении судьи;"},{"type":"subparagraph","number":"5","text":"вносит Председателю Верховного Суда представление о прекращении полномочий мирового судьи, судьи Кутузовского районного суда или Верховного судьи;"},{"type":"subparagraph","number":"6","text":"утверждает правила внутреннего судейского распорядка;"},{"type":"subparagraph","number":"7","text":"рассматривает вопросы конфликта интересов и судейской этики;"},{"type":"subparagraph","number":"8","text":"осуществляет иные организационные полномочия, не относящиеся к разрешению конкретных дел."}]}],"node_id":"36"},{"type":"article","number":"37","title":"Дисциплинарная ответственность судьи","children":[{"type":"paragraph","number":"1","text":"Дисциплинарным проступком является виновное нарушение судьей обязанностей, правил судейской этики или процессуальных требований, которое существенно умаляет авторитет судебной власти либо нарушает права участников процесса."},{"type":"paragraph","number":"2","text":"Не является дисциплинарным проступком само по себе изменение или отмена судебного акта вышестоящей инстанцией."},{"type":"paragraph","number":"3","text":"При определении взыскания учитываются характер нарушения, его последствия, форма вины, повторность и влияние на права участников процесса."}],"node_id":"37"},{"type":"article","number":"38","title":"Дисциплинарные взыскания","children":[{"type":"paragraph","text":"К судье могут применяться:","children":[{"type":"subparagraph","number":"1","text":"предупреждение;"},{"type":"subparagraph","number":"2","text":"выговор;"},{"type":"subparagraph","number":"3","text":"строгий выговор;"},{"type":"subparagraph","number":"4","text":"временное отстранение от рассмотрения дел;"},{"type":"subparagraph","number":"5","text":"прекращение полномочий."},{"type":"bullet","text":"Дисциплинарное решение должно быть мотивированным."}]}],"node_id":"38"},{"type":"article","number":"39","title":"Прекращение полномочий судьи","children":[{"type":"paragraph","text":"Полномочия мирового судьи, судьи Кутузовский районного суда или Верховного судьи прекращаются:","children":[{"type":"subparagraph","number":"1","text":"по собственному заявлению;"},{"type":"subparagraph","number":"2","text":"в случае утраты права занимать должность;"},{"type":"subparagraph","number":"3","text":"в случае вступления в силу обвинительного судебного акта, несовместимого со статусом судьи;"},{"type":"subparagraph","number":"4","text":"вследствие стойкой невозможности исполнять обязанности;"},{"type":"subparagraph","number":"5","text":"за грубый или неоднократный дисциплинарный проступок;"},{"type":"subparagraph","number":"6","text":"при выявлении обстоятельств, исключавших назначение на должность."},{"type":"bullet","text":"Решение о прекращении полномочий принимается Председателем Верховного Суда на основании закона и, в дисциплинарных случаях, с учетом заключения Высшей квалификационной коллегии судей."}]}],"node_id":"39"},{"type":"article","number":"40","title":"Прекращение полномочий Председателя Верховного Суда","children":[{"type":"paragraph","number":"1","text":"Полномочия Председателя Верховного Суда прекращаются:","children":[{"type":"subparagraph","number":"1","text":"по собственному заявлению;"},{"type":"subparagraph","number":"2","text":"в случае утраты установленных законом требований к должности;"},{"type":"subparagraph","number":"3","text":"в случае вступления в силу обвинительного судебного акта;"},{"type":"subparagraph","number":"4","text":"вследствие стойкой невозможности исполнения обязанностей;"},{"type":"subparagraph","number":"5","text":"за грубое нарушение Конституции, федерального законодательства или принципа независимости правосудия."}]},{"type":"paragraph","number":"2","text":"Решение о прекращении полномочий Председателя Верховного Суда принимается Федеральным Правительством или Верховным Судом по результатам рассмотрения дела."},{"type":"paragraph","number":"3","text":"При дисциплинарном основании до принятия решения может быть запрошено заключение Высшей квалификационной коллегии судей."},{"type":"paragraph","number":"4","text":"Прекращение полномочий Председателя Верховного Суда не влечет автоматической отмены вынесенных им судебных актов."}],"node_id":"40"}]},{"type":"chapter","number":"V","title":"ОРГАНИЗАЦИЯ СУДОПРОИЗВОДСТВА​","children":[{"type":"article","number":"41","title":"Виды судебного производства","children":[{"type":"paragraph","text":"В РО осуществляются:","children":[{"type":"subparagraph","number":"1","text":"уголовное судопроизводство;"},{"type":"subparagraph","number":"2","text":"производство по делам об административных правонарушениях;"},{"type":"subparagraph","number":"3","text":"гражданское и имущественное судопроизводство;"},{"type":"subparagraph","number":"4","text":"трудовое судопроизводство;"},{"type":"subparagraph","number":"5","text":"производство по жалобам на действия и акты государственных органов;"},{"type":"subparagraph","number":"6","text":"конституционное и нормативное производство;"},{"type":"subparagraph","number":"7","text":"иные виды производства, установленные законом."}]},{"type":"note","text":"Не допускается разделение судебных процессов, охватывающих одну ситуацию, в несколько разных дел. Так, например, не допускается обязать истца подавать административное исковое заявление об оспаривании ареста и отдельного гражданского иска о требовании компенсации. Все подобные ситуации рассматриваются в рамках одного судебного процесса, в случае подачи истцом разных исков по одной ситуации - они подлежат объединению в одно производство с целью экономии ресурсов суда и обеспечения более быстрого судебного разбирательства."}],"node_id":"41"},{"type":"article","number":"42","title":"Право на обращение в суд","children":[{"type":"paragraph","number":"1","text":"Лицо вправе обратиться в суд за защитой своих прав и законных интересов."},{"type":"paragraph","number":"2","text":"Государственный орган или должностное лицо вправе обратиться в суд в пределах предоставленной законом компетенции."},{"type":"paragraph","number":"3","text":"Адвокат вправе обращаться в суд от имени доверителя."},{"type":"paragraph","number":"4","text":"Прокурор вправе обращаться в суд в защиту публичного интереса, государства, гражданина или неопределенного круга лиц в случаях, установленных федеральным законом."},{"type":"paragraph","number":"5","text":"Следственный комитет вправе обращаться в суд за разрешением вопросов, отнесенных процессуальным законодательством к судебному контролю."},{"type":"paragraph","number":"6","text":"Анонимное обращение не является основанием для возбуждения судебного производства, если законом прямо не предусмотрено иное."}],"node_id":"42"},{"type":"article","number":"43","title":"Форма обращения","children":[{"type":"paragraph","number":"1","text":"Обращение в суд может быть подано в форме искового заявления, жалобы, ходатайства, представления либо иного процессуального документа."},{"type":"paragraph","number":"2","text":"Обращение должно позволять определить заявителя, предмет требования, обстоятельства, на которых оно основано, и желаемый способ судебной защиты."},{"type":"paragraph","number":"3","text":"Суд не вправе отказать в принятии обращения исключительно по формальным причинам, которые могут быть устранены без изменения существа требований."},{"type":"paragraph","number":"4","text":"При наличии устранимых недостатков суд предоставляет разумный срок для их исправления."}],"node_id":"43"},{"type":"article","number":"44","title":"Срок первоначального рассмотрения обращения","children":[{"type":"paragraph","number":"1","text":"Судья обязан начать обработку поступившего искового заявления, жалобы или иного обращения не позднее сорока восьми часов с момента его поступления."},{"type":"paragraph","number":"2","text":"В пределах указанного срока судья принимает одно из решений:","children":[{"type":"subparagraph","number":"1","text":"принять обращение к производству;"},{"type":"subparagraph","number":"2","text":"оставить его без движения с указанием недостатков;"},{"type":"subparagraph","number":"3","text":"возвратить или отказать в принятии при наличии предусмотренных законом оснований;"},{"type":"subparagraph","number":"4","text":"передать по подсудности."}]},{"type":"paragraph","number":"3","text":"Отказ должен быть мотивированным и содержать все выявленные на момент рассмотрения существенные недостатки обращения."},{"type":"paragraph","number":"4","text":"Повторный отказ по новому основанию, которое существовало и могло быть выявлено при первоначальном рассмотрении, не допускается, если заявитель исправил все ранее указанные недостатки."}],"node_id":"44"},{"type":"article","number":"45","title":"Первые процессуальные меры","children":[{"type":"paragraph","number":"1","text":"После принятия дела к производству суд обязан не позднее сорока восьми часов совершить необходимые первоначальные процессуальные действия."},{"type":"paragraph","number":"2","text":"К таким действиям относятся назначение заседания, извещение участников, истребование материалов, направление поручения компетентному органу, разрешение неотложного ходатайства либо иное действие, необходимое для движения дела."},{"type":"paragraph","number":"3","text":"Суд не проводит предварительное расследование или производство по делу об административном правонарушении вместо компетентного государственного органа. Если в исковом заявлении, жалобе либо приложенных к ним материалах содержатся сведения, указывающие на возможное совершение преступления или административного правонарушения, суд направляет копию соответствующего обращения и приложенных материалов в компетентный государственный орган по подследственности или подведомственности для проведения проверки и принятия процессуального решения."},{"type":"paragraph","number":"4","text":"Компетентный государственный орган обязан провести проверку в течение 72 часов с момента получения материалов, и по ее результатам направить суду принятое процессуальное решение и материалы проверки, имеющие значение для рассматриваемого судом дела. Если по результатам проверки возбуждено уголовное дело или производство по делу об административном правонарушении, суду также предоставляются материалы соответствующего расследования или производства в объеме, допустимом законом и необходимом для рассмотрения дела."},{"type":"paragraph","number":"5","text":"Суд вправе рассматривать дело об уголовном преступлении или административном правонарушении даже если компетентным органом было отказано в возбуждении уголовного дела или дела об административном правонарушении, или по результатам проверки обвинения не выдвигались. Суд вправе рассматривать дело полностью самостоятельно, опираясь на позицию органа, однако не ограничиваясь ей."},{"type":"paragraph","number":"6","text":"Если для рассмотрения дела необходимы дополнительные материалы, суд вправе истребовать их либо обязать компетентный орган совершить предусмотренные законом действия."}],"node_id":"45"},{"type":"article","number":"46","title":"Место проведения судебных заседаний","children":[{"type":"paragraph","number":"1","text":"Очные судебные заседания проводятся в специально определённых помещениях суда."},{"type":"paragraph","number":"2","text":"Проведение судебного заседания в ином месте допускается только в случаях, прямо предусмотренных федеральным законодательством либо обусловленных необходимостью обеспечения безопасности участников судопроизводства."},{"type":"paragraph","number":"3","text":"Заочное рассмотрение, вынесение отдельных процессуальных определений и рассмотрение письменных ходатайств не требуют физического присутствия сторон в зале суда."}],"node_id":"46"},{"type":"article","number":"47","title":"Извещение участников","children":[{"type":"paragraph","number":"1","text":"Лица, участвующие в деле, должны быть заблаговременно уведомлены о дате, времени и месте заседания."},{"type":"paragraph","number":"2","text":"Извещение может осуществляться лично, посредством доступных средств связи, электронной почтой, официальным уведомлением либо иным способом, позволяющим подтвердить факт извещения."},{"type":"paragraph","number":"3","text":"Лицо обязано самостоятельно и добросовестно получать информацию о движении дела после того, как ему впервые стало известно о принятии дела к производству."}],"node_id":"47"},{"type":"article","number":"48","title":"Открытое и закрытое заседание","children":[{"type":"paragraph","number":"1","text":"В открытом заседании вправе присутствовать лица, не являющиеся участниками процесса, если они соблюдают установленный порядок."},{"type":"paragraph","number":"2","text":"Фото-, видео- и аудиофиксация участниками и присутствующими лицами допускается с учетом требований федерального законодательства и законных распоряжений председательствующего."},{"type":"paragraph","number":"3","text":"В закрытом заседании присутствуют только участники процесса, суд, сотрудники аппарата суда, охрана и иные лица, допущенные судом."},{"type":"paragraph","number":"4","text":"Разглашение сведений закрытого заседания в нарушение закона влечёт установленную ответственность."}],"node_id":"48"},{"type":"article","number":"49","title":"Порядок в судебном заседании","children":[{"type":"paragraph","number":"1","text":"Председательствующий руководит заседанием и обеспечивает соблюдение процессуального порядка."},{"type":"paragraph","number":"2","text":"Участники обязаны обращаться к суду уважительно, соблюдать установленный порядок и не препятствовать выступлениям других лиц."},{"type":"paragraph","number":"3","text":"Суд вправе сделать предупреждение, ограничить явно злоупотребляющее выступление, удалить нарушителя из зала либо наложить судебный штраф в случаях, установленных законом."},{"type":"paragraph","number":"4","text":"Ограничение участника не должно лишать его реальной возможности представить позицию по делу."}],"node_id":"49"},{"type":"article","number":"50","title":"Неявка участников","children":[{"type":"paragraph","number":"1","text":"Неявка лица, которое не было надлежащим образом извещено, является основанием для отложения рассмотрения, если участие такого лица необходимо."},{"type":"paragraph","number":"2","text":"При надлежащем извещении суд вправе рассмотреть дело в отсутствие участника, если его явка не признана обязательной и отсутствуют уважительные причины неявки."},{"type":"paragraph","number":"3","text":"Участник вправе заранее просить о рассмотрении дела в его отсутствие."},{"type":"paragraph","number":"4","text":"Заочное рассмотрение уголовного дела допускается только в пределах, прямо установленных процессуальным законодательством и с обеспечением права на защиту."}],"node_id":"50"},{"type":"article","number":"51","title":"Ходатайства и дополнительные обращения","children":[{"type":"paragraph","number":"1","text":"Ходатайства, дополнения, заявления и иные обращения в рамках уже принятого дела должны быть рассмотрены не позднее сорока восьми часов с момента подачи, если характер вопроса не требует немедленного разрешения в заседании."},{"type":"paragraph","number":"2","text":"Решение по ходатайству должно быть мотивировано, если оно ограничивает процессуальное право либо влияет на дальнейшее движение дела."},{"type":"paragraph","number":"3","text":"Суд вправе разрешить простое организационное ходатайство устно с занесением результата в материалы дела."}],"node_id":"51"},{"type":"article","number":"52","title":"Разумные сроки","children":[{"type":"paragraph","number":"1","text":"Суд обязан осуществлять производство без необоснованного затягивания."},{"type":"paragraph","number":"2","text":"Намеренное затягивание процесса судьей, участником дела, государственным органом или представителем запрещается."},{"type":"paragraph","number":"3","text":"Суд вправе устанавливать разумные сроки представления документов и совершения процессуальных действий."},{"type":"paragraph","number":"4","text":"Злоупотребление процессуальными правами может повлечь судебный штраф или иные последствия, предусмотренные законом."}],"node_id":"52"}]},{"type":"chapter","number":"VI","title":"СУДЕБНЫЕ АКТЫ И ИХ ОБЖАЛОВАНИЕ​","children":[{"type":"article","number":"53","title":"Виды судебных актов","children":[{"type":"paragraph","text":"Суд принимает:","children":[{"type":"subparagraph","number":"1","text":"приговор — итоговый акт по уголовному делу;"},{"type":"subparagraph","number":"2","text":"решение — итоговый акт по гражданскому, трудовому, административному или иному спору;"},{"type":"subparagraph","number":"3","text":"постановление — акт Верховного Суда по вопросам конституционного контроля, толкования, особой подсудности и иным вопросам или акт окончательный акт суда по вопросам, не разрешаемым решением или определением, а равно как равнозаменяющий решение;"},{"type":"subparagraph","number":"4","text":"определение — промежуточный или организационный процессуальный акт, который в предусмотренных законом случаях может быть обжалован отдельно от итогового судебного акта путем подачи частной жалобы;"},{"type":"subparagraph","number":"5","text":"судебный приказ или судебный запрет — в случаях, предусмотренных законом."}]}],"node_id":"53"},{"type":"article","number":"54","title":"Требования к судебному акту","children":[{"type":"paragraph","number":"1","text":"Итоговый судебный акт должен быть законным, обоснованным и мотивированным."},{"type":"paragraph","number":"2","text":"В акте указываются установленные обстоятельства, оценка существенных доказательств, применяемые нормы права, выводы суда и порядок обжалования."},{"type":"paragraph","number":"3","text":"Суд не вправе основывать решение на доказательстве, с которым сторона была лишена разумной возможности ознакомиться и высказать возражения, кроме сведений, доступ к которым ограничен законом с применением специальных процессуальных гарантий."}],"node_id":"54"},{"type":"article","number":"55","title":"Срок изготовления мотивированного решения","children":[{"type":"paragraph","number":"1","text":"Мотивированный итоговый судебный акт должен быть изготовлен и опубликован либо доведен до участников не позднее сорока восьми часов после окончания рассмотрения дела."},{"type":"paragraph","number":"2","text":"Если в заседании оглашена только резолютивная часть, срок исчисляется с момента ее оглашения."},{"type":"paragraph","number":"3","text":"Увеличение срока допускается только при объективной сложности дела и должно быть отдельно мотивировано."}],"node_id":"55"},{"type":"article","number":"56","title":"Вступление судебного акта в силу","children":[{"type":"paragraph","number":"1","text":"Судебный акт вступает в законную силу после истечения срока на его обжалование либо после окончания предусмотренного законом обжалования."},{"type":"paragraph","number":"2","text":"Акты, подлежащие немедленному исполнению, вступают в соответствующей части в силу с момента объявления или публикации."},{"type":"paragraph","number":"3","text":"Определение о временной обеспечительной мере действует в пределах срока, установленного судом."}],"node_id":"56"},{"type":"article","number":"57","title":"Апелляционное обжалование","children":[{"type":"paragraph","number":"1","text":"Итоговый судебный акт мирового судьи может быть обжалован в Кутузовский районный суд в апелляционном порядке."},{"type":"paragraph","number":"2","text":"Апелляционный судебный акт Кутузовский районного суда, вынесенный по результатам пересмотра акта мирового судьи, является окончательным актом апелляционной инстанции и повторному апелляционному обжалованию не подлежит. Его дальнейший пересмотр осуществляется в кассационном порядке Верховным Судом РО."},{"type":"paragraph","number":"3","text":"Итоговый судебный акт Кутузовский районного суда, вынесенный им как судом первой инстанции, может быть обжалован в Верховный Суд РО в апелляционном порядке."},{"type":"paragraph","number":"4","text":"Право на апелляцию имеют стороны, прокурор, участвующий в деле, и иные лица, чьи права непосредственно затронуты судебным актом."},{"type":"paragraph","number":"5","text":"Срок, форма и содержание апелляционной жалобы устанавливаются процессуальным законодательством."},{"type":"paragraph","number":"6","text":"Кутузовский районный суд и Верховный Суд РО при апелляционном рассмотрении не связаны правовой оценкой нижестоящей инстанции."},{"type":"paragraph","number":"7","text":"Апелляционная жалоба может быть подана в течение 72 часов с момента публикации решения в полном объеме."}],"node_id":"57"},{"type":"article","number":"57.1","title":"Частная жалоба на определение суда","children":[{"type":"paragraph","number":"1","text":"Определение суда может быть обжаловано отдельно от приговора, решения или иного итогового судебного акта путем подачи частной жалобы в случаях, прямо предусмотренных федеральным законодательством, а также когда такое определение препятствует дальнейшему движению дела либо непосредственно и существенно затрагивает права, свободы или законные интересы участника процесса."},{"type":"paragraph","number":"2","text":"Частная жалоба может быть подана, в частности, на определение:","children":[{"type":"subparagraph","number":"1","text":"об отказе в принятии обращения, о его возвращении либо об оставлении без движения;"},{"type":"subparagraph","number":"2","text":"о передаче дела по подсудности;"},{"type":"subparagraph","number":"3","text":"о приостановлении производства по делу, прекращении производства либо оставлении требования без рассмотрения;"},{"type":"subparagraph","number":"4","text":"о восстановлении или об отказе в восстановлении процессуального срока;"},{"type":"subparagraph","number":"5","text":"о применении, изменении или отмене обеспечительной меры, судебного запрета либо иной временной меры, непосредственно ограничивающей права лица;"},{"type":"subparagraph","number":"6","text":"о наложении судебного штрафа;"},{"type":"subparagraph","number":"7","text":"об отказе в совершении процессуального действия, если такой отказ фактически лишает лицо возможности продолжить защиту своих прав;"},{"type":"subparagraph","number":"8","text":"в иных случаях."}]},{"type":"paragraph","number":"3","text":"Не подлежат самостоятельному обжалованию определения, разрешающие обычные организационные вопросы судебного заседания, порядок исследования доказательств, очередность выступлений и иные вопросы, которые не препятствуют дальнейшему движению дела и не влекут самостоятельного существенного ограничения прав. Возражения против таких определений могут быть включены в апелляционную или кассационную жалобу на итоговый судебный акт."},{"type":"paragraph","number":"4","text":"Частная жалоба на определение мирового судьи рассматривается Кутузовским районным судом."},{"type":"paragraph","number":"5","text":"Частная жалоба на определение Кутузовский районного суда, вынесенное им как судом первой инстанции, рассматривается Верховным Судом РО."},{"type":"paragraph","number":"6","text":"Определение Кутузовский районного суда, вынесенное по результатам рассмотрения частной жалобы на определение мирового судьи, может быть обжаловано в кассационном порядке в Верховный Суд РО при наличии существенного нарушения закона либо существенного ограничения прав участника процесса."},{"type":"paragraph","number":"7","text":"Суд, рассматривающий частную жалобу, вправе:","children":[{"type":"subparagraph","number":"1","text":"оставить определение без изменения, а жалобу без удовлетворения;"},{"type":"subparagraph","number":"2","text":"отменить определение полностью или частично и самостоятельно разрешить соответствующий процессуальный вопрос;"},{"type":"subparagraph","number":"3","text":"отменить определение и направить вопрос на новое рассмотрение в суд нижестоящей инстанции;"},{"type":"subparagraph","number":"4","text":"изменить определение в пределах заявленной жалобы."}]},{"type":"paragraph","number":"8","text":"Подача частной жалобы сама по себе не приостанавливает действие обжалуемого определения, если федеральным законом не предусмотрено иное. Суд, рассматривающий частную жалобу, вправе приостановить действие определения полностью или частично, если его исполнение до разрешения жалобы может причинить существенный вред правам лица либо сделать последующее восстановление права невозможным или чрезмерно затруднительным."},{"type":"paragraph","number":"9","text":"Форма, срок подачи и порядок рассмотрения частной жалобы устанавливаются правилами суда."},{"type":"paragraph","number":"10","text":"Частная жалоба может быть подана в течение 72 часов с момента публикации определения в полном объеме."}],"node_id":"57.1"},{"type":"article","number":"58","title":"Кассационное обжалование","children":[{"type":"paragraph","number":"1","text":"Вступивший в законную силу после апелляционного рассмотрения Кутузовским районным судом судебный акт, в том числе судебный акт по делу, первоначально рассмотренному мировым судьей, может быть обжалован в Верховный Суд РО в кассационном порядке, если имеются основания полагать, что допущено существенное нарушение закона."},{"type":"paragraph","number":"2","text":"Кассационная жалоба рассматривается Верховным Судом РО в порядке статьи 19 настоящего Федерального конституционного закона: с обязательным участием Председателя Верховного Суда РО, коллегиально или единолично Председателем Верховного Суда РО, если он ранее не участвовал в рассмотрении дела."},{"type":"paragraph","number":"3","text":"Решение кассационной инстанции может быть обжаловано в Федеральном Суде."},{"type":"paragraph","number":"4","text":"Кассационная жалоба может быть подана в течение 72 часов с момента публикации решения в полном объеме."}],"node_id":"58"},{"type":"article","number":"59","title":"Приостановление исполнения при обжаловании","children":[{"type":"paragraph","number":"1","text":"Подача апелляционной или кассационной жалобы на итоговый судебный акт не приостанавливает исполнение акта. Подача частной жалобы на определение суда влечет последствия, предусмотренные статьей 57.1 настоящего Федерального конституционного закона."}],"node_id":"59"},{"type":"article","number":"60","title":"Срок исполнения судебного акта","children":[{"type":"paragraph","number":"1","text":"На исполнение вступившего в силу судебного акта устанавливается срок до семидесяти двух часов, если самим актом или федеральным законом не установлен иной срок."},{"type":"paragraph","number":"2","text":"Срок исполнения приостанавливается на время апелляционного или кассационного обжалования в случаях, предусмотренных статьей 59 настоящего Федерального конституционного закона."},{"type":"paragraph","number":"3","text":"Лицо или орган, объективно не способные исполнить акт в срок, обязаны до истечения срока обратиться в суд с мотивированным заявлением о продлении."},{"type":"paragraph","number":"4","text":"Самовольное неисполнение судебного акта не допускается."}],"node_id":"60"},{"type":"article","number":"61","title":"Пересмотр по новым или вновь открывшимся обстоятельствам","children":[{"type":"paragraph","number":"1","text":"Вступивший в силу судебный акт может быть пересмотрен, если выявлены существенные обстоятельства, которые существовали, но не были и не могли быть известны при рассмотрении дела, либо возникли новые юридически значимые обстоятельства."},{"type":"paragraph","number":"2","text":"К таким обстоятельствам могут относиться установленная фальсификация доказательств, заведомо ложные показания, преступные действия участника или судьи, отмена акта, на котором было основано решение, либо признание примененной нормы неконституционной."},{"type":"paragraph","number":"3","text":"Пересмотр осуществляет суд, принявший акт, либо иной состав Верховного Суда, если это необходимо для обеспечения беспристрастности."}],"node_id":"61"},{"type":"article","number":"62","title":"Исправление и дополнительный судебный акт","children":[{"type":"paragraph","number":"1","text":"Суд вправе исправить очевидную описку, арифметическую ошибку либо техническую неточность без изменения существа решения."},{"type":"paragraph","number":"2","text":"Если суд не разрешил одно из заявленных требований, вопрос о судебных расходах или иной обязательный вопрос, он вправе принять дополнительный судебный акт."},{"type":"paragraph","number":"3","text":"Дополнительный акт является частью первоначального решения и может быть обжалован в том же порядке."}],"node_id":"62"},{"type":"article","number":"63","title":"Частное определение суда","children":[{"type":"paragraph","number":"1","text":"Если при рассмотрении дела или при иных обстоятельствах суд выявил нарушение закона, системный недостаток деятельности государственного органа либо обстоятельства, способствовавшие правонарушению, он вправе вынести частное определение."},{"type":"paragraph","number":"2","text":"Частное определение направляется компетентному государственному органу или должностному лицу для рассмотрения и принятия мер."},{"type":"paragraph","number":"3","text":"Частное определение также может быть вынесено в качестве разрешения вопроса о виновности лица в совершении им преступления или правонарушения, если таковое, на усмотрение суда, видится ему очевидным и не требует дополнительного расследования соответствующими органами."},{"type":"paragraph","number":"4","text":"Частное определение суда подлежит обжалованию по тем же правилам как и окончательный акт суда."}],"node_id":"63"},{"type":"article","number":"64","title":"Судебный запрет и обеспечительные меры","children":[{"type":"paragraph","number":"1","text":"Для защиты прав участника процесса и обеспечения исполнения будущего решения суд вправе временно запретить лицу совершать определенное действие либо обязать сохранить существующее положение."},{"type":"paragraph","number":"2","text":"Судебный запрет должен быть соразмерным, мотивированным и ограниченным по предмету и сроку."},{"type":"paragraph","number":"3","text":"В качестве обеспечительной меры может применяться временное отстранение от исполнения отдельных должностных полномочий, запрет распоряжения спорным имуществом, запрет приближения и иные предусмотренные законом меры."},{"type":"paragraph","number":"4","text":"Обеспечительная мера не означает признание лица виновным."}],"node_id":"64"}]},{"type":"chapter","number":"VII","title":"СУДЕБНЫЙ КОНТРОЛЬ ЗА ГОСУДАРСТВЕННЫМИ ОРГАНАМИ​","children":[{"type":"article","number":"65","title":"Оспаривание актов и действий государственных органов","children":[{"type":"paragraph","number":"1","text":"Гражданин, организация или государственный орган вправе оспорить в суде акт, решение, действие или бездействие государственного органа либо должностного лица, если полагает, что ими нарушены права, компетенция или закон."},{"type":"paragraph","number":"2","text":"Суд проверяет наличие полномочия, законного основания, соблюдение процедуры и соразмерность вмешательства."},{"type":"paragraph","number":"3","text":"Оспаривание процессуального решения прокуратуры, Следственного комитета, МВД или ФСБ осуществляется с учетом специальных норм процессуального законодательства."}],"node_id":"65"},{"type":"article","number":"66","title":"Способы судебной защиты","children":[{"type":"paragraph","text":"Установив нарушение, суд вправе:","children":[{"type":"subparagraph","number":"1","text":"признать акт, решение, действие или бездействие незаконным;"},{"type":"subparagraph","number":"2","text":"отменить незаконный индивидуальный акт;"},{"type":"subparagraph","number":"3","text":"признать нормативный акт не подлежащим применению;"},{"type":"subparagraph","number":"4","text":"обязать орган совершить предусмотренное законом действие;"},{"type":"subparagraph","number":"5","text":"запретить незаконное действие;"},{"type":"subparagraph","number":"6","text":"восстановить лицо в должности или ином нарушенном праве;"},{"type":"subparagraph","number":"7","text":"присудить материальную или моральную компенсацию;"},{"type":"subparagraph","number":"8","text":"отменить незаконно наложенное взыскание;"},{"type":"subparagraph","number":"9","text":"применить иные предусмотренные законом способы защиты."}]}],"node_id":"66"},{"type":"article","number":"67","title":"Отстранение и прекращение полномочий руководителя государственной организации","children":[{"type":"paragraph","number":"1","text":"Верховный Суд вправе временно отстранить либо окончательно прекратить полномочия руководителя государственной организации или его заместителя, если в рамках рассмотренного дела установлено:","children":[{"type":"subparagraph","number":"1","text":"совершение преступления, несовместимого с дальнейшим исполнением должности;"},{"type":"subparagraph","number":"2","text":"грубое или неоднократное злоупотребление должностными полномочиями;"},{"type":"subparagraph","number":"3","text":"систематическое неисполнение вступивших в силу судебных актов;"},{"type":"subparagraph","number":"4","text":"иное тяжкое нарушение закона, которое делает продолжение исполнения должности несовместимым с публичными интересами."}]},{"type":"paragraph","number":"2","text":"Решение об окончательном прекращении полномочий принимается только мотивированным актом Верховного Суда."},{"type":"paragraph","number":"3","text":"Временное отстранение может применяться как обеспечительная мера до окончательного разрешения дела."},{"type":"paragraph","number":"4","text":"Настоящая статья не применяется к Премьер-министру РО, порядок отрешения которого определяется Конституцией и Федеральным конституционным законом о Премьер-министре и Правительстве, а также к судьям, дисциплинарный порядок которых установлен настоящим Федеральным конституционным законом."}],"node_id":"67"},{"type":"article","number":"68","title":"Судебные запросы и истребование материалов","children":[{"type":"paragraph","number":"1","text":"Суд вправе истребовать у государственных органов документы, видеозаписи, материалы и сведения, необходимые для рассмотрения дела."},{"type":"paragraph","number":"2","text":"Государственный орган обязан предоставить запрошенный материал в установленный судом срок либо мотивированно сообщить о законном препятствии."},{"type":"paragraph","number":"3","text":"Сведения ограниченного доступа предоставляются с соблюдением установленного режима тайны."},{"type":"paragraph","number":"4","text":"Суд не вправе требовать сведения, очевидно не относящиеся к рассматриваемому делу."}],"node_id":"68"},{"type":"article","number":"69","title":"Судебный контроль за мерами принуждения","children":[{"type":"paragraph","number":"1","text":"В случаях, установленных процессуальным законодательством, суд разрешает либо проверяет законность обыска, ареста, ограничения тайны сообщений, применения специальных мер в отношении неприкосновенных лиц и иных существенных ограничений прав."},{"type":"paragraph","number":"2","text":"Судебное решение должно содержать предмет, пределы и основание разрешенной меры."},{"type":"paragraph","number":"3","text":"Судебное разрешение не предоставляет право проводить действия, не указанные в нём или не вытекающие из закона."},{"type":"paragraph","number":"4","text":"Законность уже проведённой неотложной меры может быть проверена судом в последующем порядке."}],"node_id":"69"}]},{"type":"chapter","number":"VIII","title":"АППАРАТ СУДА И ОБЕСПЕЧЕНИЕ ДЕЯТЕЛЬНОСТИ​","children":[{"type":"article","number":"70","title":"Аппарат суда","children":[{"type":"paragraph","number":"1","text":"Для организационного обеспечения деятельности судов формируется аппарат суда."},{"type":"paragraph","number":"2","text":"К аппарату суда могут относиться помощники судей, секретари и иные служащие, предусмотренные внутренней структурой."},{"type":"paragraph","number":"3","text":"Работники аппарата не осуществляют правосудие и не вправе самостоятельно принимать судебные решения."},{"type":"paragraph","number":"4","text":"Руководство аппаратом суда осуществляется администратором суда."}],"node_id":"70"},{"type":"article","number":"71","title":"Помощник судьи","children":[{"type":"paragraph","number":"1","text":"Помощник судьи содействует подготовке дел и судебных заседаний."},{"type":"paragraph","number":"2","text":"Помощник вправе изучать поступившие материалы, готовить проекты процессуальных документов, вести учет дел, обеспечивать извещение участников и фиксирование хода заседания."},{"type":"paragraph","number":"3","text":"Помощник действует по поручению судьи и не вправе подменять его при принятии решений."},{"type":"paragraph","number":"4","text":"Доступ помощника к сведениям ограниченного доступа допускается в объеме, необходимом для исполнения обязанностей."}],"node_id":"71"},{"type":"article","number":"72","title":"Судебный пристав и охрана суда","children":[{"type":"paragraph","number":"1","text":"Для обеспечения порядка и исполнения судебных актов суд вправе привлекать судебного пристава либо назначенного сотрудника компетентной силовой государственной организации."},{"type":"paragraph","number":"2","text":"Судебный пристав:","children":[{"type":"subparagraph","number":"1","text":"обеспечивает порядок в зале суда;"},{"type":"subparagraph","number":"2","text":"исполняет распоряжения председательствующего по обеспечению безопасности;"},{"type":"subparagraph","number":"3","text":"обеспечивает доставление лиц в случаях, предусмотренных законом;"},{"type":"subparagraph","number":"4","text":"содействует исполнению судебных актов;"},{"type":"subparagraph","number":"5","text":"осуществляет иные функции, прямо возложенные законом или судебным актом."}]},{"type":"paragraph","number":"3","text":"Судебный пристав не вправе самостоятельно изменять содержание судебного акта или расширять предусмотренные им меры."},{"type":"paragraph","number":"4","text":"В качестве судебного пристава могут выступать любые сотрудники правоохранительных органов по запросу суда и в количестве сотрудников, определенных судом."}],"node_id":"72"},{"type":"article","number":"73","title":"Видеофиксация судебного процесса","children":[{"type":"paragraph","number":"1","text":"Суд обеспечивает фиксацию значимых судебных заседаний техническими средствами при наличии такой возможности."},{"type":"paragraph","number":"2","text":"Запись судебного заседания хранится в течение срока, установленного процессуальным законодательством."},{"type":"paragraph","number":"3","text":"Запись предоставляется участнику дела, вышестоящему суду, прокуратуре или иному уполномоченному органу в предусмотренных законом случаях."},{"type":"paragraph","number":"4","text":"Умышленное уничтожение, сокрытие или фальсификация обязательной записи влечёт ответственность."}],"node_id":"73"},{"type":"article","number":"74","title":"Исполнение судебных актов государственными органами","children":[{"type":"paragraph","number":"1","text":"Государственный орган, которому адресован судебный акт, обязан обеспечить его исполнение."},{"type":"paragraph","number":"2","text":"Если для исполнения необходимо действие нескольких организаций, они обязаны взаимодействовать в пределах своей компетенции."},{"type":"paragraph","number":"3","text":"Правительство обеспечивает организационные условия для исполнения судебных актов, но не вправе изменять их содержание."},{"type":"paragraph","number":"4","text":"Суд вправе запросить подтверждение исполнения."}],"node_id":"74"}]},{"type":"chapter","number":"IX","title":"ПРАВОВЫЕ ПОЗИЦИИ ВЕРХОВНОГО СУДА И ЗАКЛЮЧИТЕЛЬНЫЕ ПОЛОЖЕНИЯ​","children":[{"type":"article","number":"75","title":"Правовые позиции Верховного Суда","children":[{"type":"paragraph","number":"1","text":"Верховный Суд вправе обобщать судебную практику и формировать правовые позиции по вопросам применения действующих норм."},{"type":"paragraph","number":"2","text":"Правовая позиция обязательна для Кутузовский районного суда, мировых судей и государственных органов в части толкования действующей нормы, а равно как может создавать новую норму, не противоречащую законодательству."},{"type":"paragraph","number":"3","text":"При изменении закона ранее сформированная позиция применяется только в части, не противоречащей новой норме."}],"node_id":"75"},{"type":"article","number":"76","title":"Постановления Верховного Суда общего характера","children":[{"type":"paragraph","number":"1","text":"Для разъяснения судебной практики Верховный Суд вправе принимать постановления общего характера."},{"type":"paragraph","number":"2","text":"Такие постановления подлежат официальному опубликованию."},{"type":"paragraph","number":"3","text":"Постановление общего характера применяется как обязательное толкование действующего законодательства в пределах статьи 75 настоящего Федерального конституционного закона."}],"node_id":"76"},{"type":"article","number":"77","title":"Законодательная инициатива Верховного Суда","children":[{"type":"paragraph","number":"1","text":"Верховный Суд обладает правом законодательной инициативы по вопросам судебной власти, судопроизводства и устранения выявленных в практике пробелов и противоречий."},{"type":"paragraph","number":"2","text":"Проект нормативного правового акта вносится в Парламент в порядке, установленном Федеральным конституционным законом «О Парламенте РО»."},{"type":"paragraph","number":"3","text":"Судебная законодательная инициатива не может использоваться для изменения закона в интересах разрешения конкретного дела."}],"node_id":"77"}]},{"type":"chapter","number":"X","title":"Судебная пошлина.","children":[{"type":"article","number":"77","title":"Судебная пошлина","children":[{"type":"paragraph","number":"1","text":"При обращении в Суд, истец обязан уплатить судебную пошлину в целях финансирования деятельности судейского состава."},{"type":"paragraph","number":"2","text":"От уплаты государственных пошлин по уголовным, административным делам, делам об административных правонарушениях, рассматриваемых судами, освобождаются Офис генерального прокурора."},{"type":"paragraph","number":"3","text":"Судебная пошлина уплачивается заявителем в наличной либо безналичной форме при подаче искового заявления или жалобы. К заявлению прилагаются документы об оплате пошлины."},{"type":"paragraph","number":"4","text":"Судебная пошлина в наличной форме уплачивается посредством передачи денежных средств действующему председателю Верховного суда."},{"type":"paragraph","number":"5","text":"Судебная пошлина в безналичной форме уплачивается посредством банковского перевода на счет действующего председателя Верховного суда."},{"type":"note","text":"Факт уплаты судебной пошлины в безналичной форме подтверждается письменным уведомлением банка о списании денежных средств."},{"type":"paragraph","number":"6","text":"Размеры судебных пошлин по делам и обращениям, рассматриваемым судами РО, сумма оплаты за процедуру юридической реабилитации, а также реквизиты счетов для перевода денежных средств устанавливаются актом Председателя Верховного суда РО и публикуются на портале РО."},{"type":"note","text":"При издании соответствующего акта Председатель Верховного суда ограничен следующими максимальными пределами размеров судебных пошлин: при подаче искового заявления в Мировой суд - не более 10.000; при подаче искового заявления или иного обращения в Верховный суд - не более 20.000; при подаче жалобы в кассационном порядке, а равно при подаче частной жалобы - не более 15.000."},{"type":"paragraph","number":"7","text":"Государственные организации, а также сотрудники Прокуратуры при обращении к суду в рамках исполнения своих должностных обязанностей освобождены от обязанности по уплате пошлины. Нормативно-правовой акт подписан Премьер-министром РО 25.08.2026 Марк Брагин ​"}],"node_id":"77-1"}]}]};
